(* [comment removed for export] *)
Lemma push_back_fast_x : forall (LB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (o cap p c sp r : Z) (s : list Z),
  PMSA.cps_asan L ar HI 1056004 r sp PMSA.STR_SCR LB FF LK cr A 0
      (fun R M => Z.of_nat (length s) + 1 < cap /\ PMSA.a0 R o /\ PMSA.a1 R c /\ 0 <= c < 256 /\ PMSA.str_at L M o (PML.SLong cap p s) /\ 24 <= cap /\ In (p, cap) LB /\ shadow_blk M p cap /\
